"""One retained wave-two integration gate; no benchmark study or source edits."""
from datetime import datetime, timezone
import hashlib
import importlib.metadata
import json
import os
from pathlib import Path
import platform
import re
import subprocess
import sys
import time

ROOT = Path('/workspace/scratch/cc294adc3e2f/Fender-rhoades')
OUT = ROOT / 'build/w2-040-integration'
BUILD = ROOT / 'build/vst3'
SDK = Path('/workspace/scratch/d6370337c6a4/vst3sdk')
SOURCE_DIRS = ('include', 'src', 'apps', 'plugins', 'cmake', 'tests', 'tools',
               'schemas', 'profiles', 'data', 'fixtures', 'templates')

def utc():
    return datetime.now(timezone.utc).isoformat()

def raw_hash(raw):
    return hashlib.sha256(raw).hexdigest()

def identity(path):
    before = path.stat()
    raw = path.read_bytes()
    after = path.stat()
    if (before.st_ino,before.st_size,before.st_mtime_ns,before.st_ctime_ns) != \
       (after.st_ino,after.st_size,after.st_mtime_ns,after.st_ctime_ns):
        raise RuntimeError('Input changed while hashing: '+str(path))
    return {'bytes':len(raw),'sha256':raw_hash(raw)}

def encode(value):
    return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()

def write(name, value, *, exclusive=True):
    with (OUT/name).open('x' if exclusive else 'w',encoding='utf-8') as stream:
        json.dump(value,stream,indent=2,allow_nan=False)
        stream.write('\n')

def source_inventory():
    paths = {ROOT/'CMakeLists.txt'}
    for directory in SOURCE_DIRS:
        for path in (ROOT/directory).rglob('*'):
            if path.is_file() and '__pycache__' not in path.parts and path.suffix != '.pyc':
                paths.add(path)
    rows = {path.relative_to(ROOT).as_posix():identity(path) for path in sorted(paths)}
    return {'scope':list(SOURCE_DIRS)+['CMakeLists.txt'], 'exclusions':['__pycache__','*.pyc'],
            'files':rows,'file_count':len(rows),'canonical_files_sha256':raw_hash(encode(rows))}

def build_inventory():
    paths = set()
    for path in BUILD.rglob('*'):
        if not path.is_file() or '__pycache__' in path.parts:
            continue
        relative = path.relative_to(BUILD)
        if path.name in ('CMakeCache.txt','compile_commands.json','flags.make','link.txt','CTestTestfile.cmake') \
                or path.suffix in ('.o','.a','.so') \
                or relative.parts[0]=='VST3' \
                or (path.parent == BUILD and os.access(path,os.X_OK)):
            paths.add(path)
    rows = {path.relative_to(BUILD).as_posix():identity(path) for path in sorted(paths)}
    return {'files':rows,'file_count':len(rows),'canonical_files_sha256':raw_hash(encode(rows))}

def check_output(command):
    return subprocess.check_output(command,cwd=ROOT,text=True).strip()

def observe(name, command, *, env_delta=None, timeout=600):
    begin, timer = utc(), time.monotonic()
    environment = os.environ.copy()
    environment['PYTHONDONTWRITEBYTECODE']='1'
    if env_delta:
        environment.update(env_delta)
    with (OUT/(name+'.stdout')).open('xb') as stdout, (OUT/(name+'.stderr')).open('xb') as stderr:
        try:
            process = subprocess.run(command,cwd=ROOT,env=environment,stdout=stdout,stderr=stderr,
                                     timeout=timeout,check=False)
            code, failure = process.returncode, None
        except subprocess.TimeoutExpired as exc:
            code, failure = None, {'type':'TimeoutExpired','timeout_seconds':exc.timeout}
    row = {'name':name,'argv':[str(value) for value in command],'cwd':str(ROOT),
           'environment_delta':{'PYTHONDONTWRITEBYTECODE':'1',**(env_delta or {})},
           'started_utc':begin,'finished_utc':utc(),'elapsed_seconds':time.monotonic()-timer,
           'exit_code':code,'failure':failure,
           'stdout':{'path':name+'.stdout',**identity(OUT/(name+'.stdout'))},
           'stderr':{'path':name+'.stderr',**identity(OUT/(name+'.stderr'))}}
    write(name+'.command.json',row)
    print(json.dumps({'command':name,'exit_code':code,'elapsed_seconds':row['elapsed_seconds']}),flush=True)
    if code != 0:
        raise SystemExit(1)
    return row

def initialize():
    sources=source_inventory()
    write('sources.before.json',sources)
    write('build.before.json',build_inventory())
    compiler=Path('/usr/bin/c++').resolve()
    package_versions={name:importlib.metadata.version(name) for name in ('numpy','scipy')}
    sdk={}
    for component in ('.','base','cmake','pluginterfaces','public.sdk'):
        path=SDK/component
        sdk[component]={'commit':check_output(['git','-C',str(path),'rev-parse','HEAD']),
                        'status_porcelain':check_output(['git','-C',str(path),'status','--porcelain'])}
    write('environment.json',{'started_utc':utc(),'head':check_output(['git','rev-parse','HEAD']),
                              'branch':check_output(['git','branch','--show-current']),
                              'python':sys.version,'python_executable':sys.executable,
                              'platform':platform.platform(),'machine':platform.machine(),
                              'packages':package_versions,'compiler':{'path':str(compiler),**identity(compiler),
                               'version':check_output([str(compiler),'--version'])},
                              'cmake_version':check_output(['cmake','--version']),'sdk':sdk,
                              'source_fingerprint':sources['canonical_files_sha256']})
    for suffix,args in [('validate',['validate']),('sync',['sync','--check']),('next',['next','--json'])]:
        observe('startup-'+suffix,['python3','tools/project.py',*args],timeout=30)
    print(json.dumps({'source_files':sources['file_count'],'source_fingerprint':sources['canonical_files_sha256']}),flush=True)

def gate():
    before=json.loads((OUT/'sources.before.json').read_bytes())
    if source_inventory()!=before:
        raise RuntimeError('Sources changed before integration start')
    observe('build',['cmake','--build','build/vst3','--config','Release','--parallel','2'])
    write('build.after-build.json',build_inventory())
    observe('ctest',['ctest','--test-dir','build/vst3','-C','Release','--output-on-failure','--no-tests=error'])
    observe('python',['python3','-m','unittest','discover','-s','tests/python','-v'],
            env_delta={'RHODES_AUDIO_PROBE':str(BUILD/'rhodes_audio_probe')})
    after=source_inventory()
    write('sources.after-tests.json',after)
    write('build.after-tests.json',build_inventory())
    if after!=before:
        raise RuntimeError('Sources changed during integration')
    print('Integration commands finished; source inventory unchanged.',flush=True)

def final_checks():
    for name,args in [('final-validate',['tools/project.py','validate']),
                      ('final-sync',['tools/project.py','sync','--check']),
                      ('final-ledger',['tools/validate_continuation_b.py','--json']),
                      ('final-docs',['tools/check_docs.py'])]:
        observe(name,['python3',*args],timeout=60)
    write('sources.final.json',source_inventory())

if __name__=='__main__':
    {'initialize':initialize,'gate':gate,'final':final_checks}[sys.argv[1]]()

